const apiItem = $('Check API Health').first();
const webItem = $('Check Web Health').first();
const api = apiItem?.json ?? {};
const web = webItem?.json ?? {};
const apiBody = api.body ?? api;
const apiOk = apiBody?.status === 'ok';
const webStatusCode = web.statusCode ?? web.status ?? web.body?.statusCode;
const webOk = Number(webStatusCode) === 200;
const issues = [];
if (api.error || apiItem?.error) {
  issues.push('API unreachable');
} else if (!apiOk) {
  issues.push('API health not ok');
}
if (web.error || webItem?.error) {
  issues.push('Web unreachable');
} else if (!webOk) {
  issues.push(`Web returned ${webStatusCode ?? 'unknown'}`);
}
return [{
  json: {
    event: issues.length ? 'health.degraded' : 'health.ok',
    workflow: 'bizos-health-monitor',
    apiStatus: apiBody?.status ?? 'unknown',
    webStatusCode: webStatusCode ?? 'unknown',
    healthy: issues.length === 0,
    issues: issues.join('; ') || 'none',
    checkedAt: new Date().toISOString(),
    title: issues.length ? '[bizOS] Health degraded' : '[bizOS] Health ok',
    message: (issues.join('; ') || 'none') + ' · API=' + (apiBody?.status ?? 'unknown') + ' · Web=' + (webStatusCode ?? 'unknown'),
    severity: issues.length ? 'critical' : 'low',
  },
}];

const item = $input.first().json;
const mailpit = $env.BIZOS_OPS_MAILPIT_URL;
const webhook = $env.BIZOS_OPS_ALERT_WEBHOOK_URL;
const to = $env.BIZOS_OPS_ALERT_EMAIL || 'ops@bizos.local';
const from = $env.BIZOS_OPS_ALERT_FROM || 'n8n@bizos.local';
const title = item.title || '[bizOS] Health degraded';
const message = item.message || item.issues || JSON.stringify(item);

async function deliver() {
  if (mailpit) {
    const url = String(mailpit).replace(/\/$/, '') + '/api/v1/send';
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        From: { Email: from, Name: 'bizOS n8n' },
        To: [{ Email: to }],
        Subject: title,
        Text: message,
      }),
    });
    if (!response.ok) {
      throw new Error('Mailpit send failed: ' + response.status + ' ' + (await response.text()));
    }
    return { deliveredVia: 'mailpit', status: 'delivered' };
  }
  if (webhook) {
    const response = await fetch(webhook, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...item, title, message }),
    });
    if (!response.ok) {
      throw new Error('Alert webhook failed: ' + response.status);
    }
    return { deliveredVia: 'webhook', status: 'delivered' };
  }
  return { deliveredVia: 'log', status: 'logged' };
}

const result = await deliver();
return [{ json: { ...item, ...result, deliveredAt: new Date().toISOString() } }];
